import"./chunk-VC46IEJQ.js";var e=(t,a,r,n,l,s,h,i)=>({name:{en:t[0],zh:t[1]},desc:{en:a[0],zh:a[1]},tour:{en:r[0],zh:r[1]},source:{confidence:n,refs:l,book:{en:s[0],zh:s[1]},unknown:{en:h[0],zh:h[1]},interpretation:{en:i[0],zh:i[1]}}}),o=["The books give no description of this.","\u4E66\u4E2D\u5BF9\u6B64\u5E76\u65E0\u63CF\u5199\u3002"],d={id:"qohor",intro:{en:"A grim inland Free City at the edge of the great Forest of Qohor. Its smiths are famed across the world, and they alone are said to keep the secret of reworking Valyrian steel. The books say little about the city itself, so this scene is dark and restrained.",zh:"\u79D1\u970D\u5C14\u662F\u4E00\u5EA7\u9634\u90C1\u7684\u5185\u9646\u81EA\u7531\u8D38\u6613\u57CE\u90A6\uFF0C\u5750\u843D\u5728\u79D1\u970D\u5C14\u5927\u68EE\u6797\u8FB9\u7F18\u3002\u57CE\u4E2D\u94C1\u5320\u540D\u95FB\u5929\u4E0B\uFF0C\u636E\u8BF4\u53EA\u6709\u4ED6\u4EEC\u8FD8\u638C\u63E1\u91CD\u94F8\u74E6\u96F7\u5229\u4E9A\u94A2\u7684\u79D8\u6CD5\u3002\u4E66\u4E2D\u5BF9\u57CE\u5E02\u672C\u8EAB\u7740\u58A8\u751A\u5C11\uFF0C\u6545\u672C\u573A\u666F\u57FA\u8C03\u6697\u6C89\u3001\u514B\u5236\u3002"},notes:{en:"From the novels: the Forest of Qohor; Qohorik-trained armourers who can rework Valyrian steel; the Black Goat as Qohor's god; the tale of the Three Thousand of Qohor, Unsullied who held the city against the Dothraki. From companion summaries: timber as a source of wealth and the Unsullied as its standing defence. Invented: the black-stone look, the plan, every building, the kilns and the walls.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u79D1\u970D\u5C14\u5927\u68EE\u6797\uFF1B\u5728\u79D1\u970D\u5C14\u5B66\u827A\u3001\u80FD\u91CD\u94F8\u74E6\u96F7\u5229\u4E9A\u94A2\u7684\u94F8\u7532\u5E08\uFF1B\u79D1\u970D\u5C14\u4EBA\u4FE1\u5949\u7684\u9ED1\u5C71\u7F8A\uFF1B\u201C\u79D1\u970D\u5C14\u4E09\u5343\u52C7\u58EB\u201D\u7684\u6545\u4E8B\u2014\u2014\u4E09\u5343\u65E0\u57A2\u8005\u4E3A\u8BE5\u57CE\u6321\u4F4F\u4E86\u591A\u65AF\u62C9\u514B\u4EBA\u3002\u51FA\u81EA\u8BBE\u5B9A\u96C6\u6458\u8981\uFF1A\u6728\u6750\u662F\u8D22\u6E90\u4E4B\u4E00\uFF0C\u57CE\u9632\u6B64\u540E\u591A\u501A\u4ED7\u65E0\u57A2\u8005\u3002\u81EA\u62DF\u90E8\u5206\uFF1A\u9ED1\u77F3\u5916\u89C2\u3001\u57CE\u5E02\u5E03\u5C40\u3001\u6240\u6709\u5EFA\u7B51\uFF0C\u4EE5\u53CA\u70AD\u7A91\u4E0E\u57CE\u5899\u3002"},tour:["forest-of-qohor","charcoal-kilns","black-walls","forges","smiths-quarter","black-goat-temple"],sources:[{ref:"agot",checked:"memory",note:{en:"A master armourer in King's Landing who trained in Qohor, and the khalasar's journey past the Forest of Qohor, recalled from memory, not re-read.",zh:"\u541B\u4E34\u4E00\u4F4D\u5728\u79D1\u970D\u5C14\u5B66\u827A\u7684\u94F8\u7532\u5E08\u5085\uFF0C\u4EE5\u53CA\u5361\u62C9\u8428\u9014\u7ECF\u79D1\u970D\u5C14\u5927\u68EE\u6797\u7684\u60C5\u8282\uFF0C\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"asos",checked:"memory",note:{en:"Valyrian steel reworked by that armourer; the Three Thousand of Qohor; oaths by the Black Goat from a Qohorik sellsword captain. Recalled, not re-read.",zh:"\u8BE5\u94F8\u7532\u5E08\u91CD\u94F8\u74E6\u96F7\u5229\u4E9A\u94A2\uFF1B\u79D1\u970D\u5C14\u4E09\u5343\u52C7\u58EB\uFF1B\u4E00\u540D\u79D1\u970D\u5C14\u7C4D\u4F63\u5175\u961F\u957F\u4EE5\u9ED1\u5C71\u7F8A\u8D77\u8A93\u3002\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Qohor alone preserving the art of reworking Valyrian steel, the Unsullied defence, and the forest as a source of wealth: confirmed via web-search summaries; pages not fetched.",zh:"\u552F\u6709\u79D1\u970D\u5C14\u4FDD\u5B58\u91CD\u94F8\u74E6\u96F7\u5229\u4E9A\u94A2\u7684\u6280\u827A\u3001\u65E0\u57A2\u8005\u5B88\u57CE\u3001\u68EE\u6797\u4E3A\u8D22\u6E90\uFF1A\u7ECF\u7F51\u7EDC\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF0C\u672A\u80FD\u6253\u5F00\u9875\u9762\u3002"}}],landmarks:{"forest-of-qohor":e(["Forest of Qohor","\u79D1\u970D\u5C14\u5927\u68EE\u6797"],["A vast, dark forest around the city; its timber is one of Qohor's sources of wealth.","\u73AF\u7ED5\u5168\u57CE\u7684\u5E7F\u88A4\u5BC6\u6797\uFF0C\u6728\u6750\u662F\u79D1\u970D\u5C14\u7684\u8D22\u6E90\u4E4B\u4E00\u3002"],["Qohor lives off the forest that hems it in.","\u79D1\u970D\u5C14\u9760\u8FD9\u7247\u5C06\u5B83\u56E2\u56E2\u56F4\u4F4F\u7684\u68EE\u6797\u4E3A\u751F\u3002"],"high",["agot","twoiaf"],["The Forest of Qohor is named in the novels; its role in the city's wealth comes from companion summaries.","\u79D1\u970D\u5C14\u5927\u68EE\u6797\u89C1\u4E8E\u5C0F\u8BF4\uFF1B\u5176\u4E3A\u57CE\u5E02\u8D22\u6E90\u4E00\u8BF4\u51FA\u81EA\u8BBE\u5B9A\u96C6\u6458\u8981\u3002"],["Its extent and tree species.","\u8303\u56F4\u4E0E\u6811\u79CD\u3002"],["Dense pine and oak; invented.","\u8302\u5BC6\u7684\u677E\u6811\u4E0E\u6A61\u6811\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"charcoal-kilns":e(["Charcoal Kilns","\u70AD\u7A91"],["Earth-covered kilns outside the walls turn the forest into fuel for the forges.","\u57CE\u5916\u8986\u571F\u7684\u70AD\u7A91\uFF0C\u628A\u6797\u6728\u70E7\u6210\u4F9B\u7ED9\u94F8\u7089\u7684\u71C3\u6599\u3002"],["Fuel for the forges is made out here.","\u94F8\u7089\u7684\u71C3\u6599\u5C31\u5728\u8FD9\u91CC\u70E7\u5236\u3002"],"low",["awoiaf"],o,["Anything about how the wood is used.","\u6728\u6750\u5982\u4F55\u5229\u7528\uFF0C\u4E66\u4E2D\u53EA\u5B57\u672A\u63D0\u3002"],["Eight small kilns, inferred from the forest-and-smith link.","\u516B\u5EA7\u5C0F\u70AD\u7A91\uFF0C\u7531\u68EE\u6797\u4E0E\u94C1\u5320\u4E4B\u95F4\u7684\u5173\u8054\u63A8\u60F3\u800C\u6765\u3002"]),"black-walls":e(["City Walls","\u57CE\u5899"],["Dark stone walls and towers ring the city; three gates open onto roads through the trees.","\u6DF1\u8272\u77F3\u5899\u4E0E\u5854\u697C\u73AF\u7ED5\u5168\u57CE\uFF0C\u4E09\u5EA7\u57CE\u95E8\u901A\u5411\u6797\u95F4\u5927\u9053\u3002"],["A dark ring of wall holds the city apart from the trees.","\u4E00\u5708\u6697\u8272\u57CE\u5899\uFF0C\u628A\u57CE\u5E02\u4E0E\u6797\u6D77\u9694\u5F00\u3002"],"low",["awoiaf"],o,["Colour, height and gates.","\u989C\u8272\u3001\u9AD8\u5EA6\u4E0E\u57CE\u95E8\u3002"],["Black stone is this scene's palette choice, not a book fact.","\u9ED1\u77F3\u53EA\u662F\u672C\u573A\u666F\u7684\u914D\u8272\u9009\u62E9\uFF0C\u5E76\u975E\u4E66\u4E2D\u4E8B\u5B9E\u3002"]),forges:e(["Forges","\u94F8\u7089"],["Low dark halls with tall chimneys and glowing furnaces where Qohorik smiths work.","\u4F4E\u77EE\u7684\u6DF1\u8272\u5DE5\u574A\uFF0C\u70DF\u56F1\u9AD8\u8038\uFF0C\u7089\u706B\u901A\u7EA2\uFF0C\u79D1\u970D\u5C14\u94C1\u5320\u5728\u6B64\u52B3\u4F5C\u3002"],["Only Qohor's smiths still know how to rework Valyrian steel.","\u5982\u4ECA\u53EA\u6709\u79D1\u970D\u5C14\u7684\u94C1\u5320\u8FD8\u61C2\u5F97\u91CD\u94F8\u74E6\u96F7\u5229\u4E9A\u94A2\u3002"],"high",["agot","asos","awoiaf"],["Qohor is famed for its smiths; a Qohor-trained armourer reforges a Valyrian steel sword in the novels, and Qohor is said to be the only place that keeps this art.","\u79D1\u970D\u5C14\u4EE5\u94C1\u5320\u95FB\u540D\uFF1B\u5C0F\u8BF4\u4E2D\u4E00\u4F4D\u5728\u79D1\u970D\u5C14\u5B66\u827A\u7684\u94F8\u7532\u5E08\u91CD\u94F8\u4E86\u4E00\u628A\u74E6\u96F7\u5229\u4E9A\u94A2\u5251\uFF0C\u636E\u8BF4\u53EA\u6709\u79D1\u970D\u5C14\u4FDD\u6709\u6B64\u9879\u6280\u827A\u3002"],["The number, size and layout of the forges.","\u94F8\u7089\u7684\u6570\u91CF\u3001\u89C4\u6A21\u4E0E\u5E03\u5C40\u3002"],["Four forge halls with chimneys and fires; invented.","\u56DB\u5EA7\u5E26\u70DF\u56F1\u4E0E\u7089\u706B\u7684\u953B\u9020\u5DE5\u574A\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"smiths-quarter":e(["Smiths' Quarter","\u94C1\u5320\u533A"],["Dense dark roofs and chimney smoke in the district around the forges.","\u94F8\u7089\u56DB\u5468\u7684\u8857\u533A\u91CC\uFF0C\u6DF1\u8272\u5C4B\u9876\u5BC6\u5BC6\u531D\u531D\uFF0C\u7089\u70DF\u7F2D\u7ED5\u3002"],["Smoke and the ring of hammers fill the lanes.","\u70DF\u96FE\u4E0E\u9524\u58F0\u5145\u65A5\u7740\u5927\u8857\u5C0F\u5DF7\u3002"],"low",["awoiaf"],o,["Districts and streets.","\u8857\u533A\u4E0E\u8857\u9053\u3002"],["Generic dense housing; invented.","\u4E00\u822C\u6027\u7684\u5BC6\u96C6\u6C11\u5C45\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"black-goat-temple":e(["Black Goat Temple","\u9ED1\u5C71\u7F8A\u795E\u6BBF"],["A dark, horned hall near the heart of the city, imagined as a shrine of the Black Goat.","\u57CE\u4E2D\u5FC3\u9644\u8FD1\u4E00\u5EA7\u9876\u751F\u53CC\u89D2\u7684\u6697\u8272\u6BBF\u5802\uFF0C\u8BBE\u60F3\u4E3A\u4F9B\u5949\u9ED1\u5C71\u7F8A\u4E4B\u6240\u3002"],["Qohor's god is the Black Goat, honoured with blood.","\u79D1\u970D\u5C14\u4EBA\u4FE1\u5949\u9ED1\u5C71\u7F8A\uFF0C\u4EE5\u9C9C\u8840\u732E\u796D\u3002"],"medium",["asos","awoiaf"],["The Black Goat is the god of Qohor, and a Qohorik sellsword swears by it; blood sacrifice is attributed to the cult in companion summaries.","\u9ED1\u5C71\u7F8A\u662F\u79D1\u970D\u5C14\u4E4B\u795E\uFF0C\u4E00\u540D\u79D1\u970D\u5C14\u7C4D\u4F63\u5175\u4FBF\u4EE5\u5B83\u8D77\u8A93\uFF1B\u8BBE\u5B9A\u96C6\u6458\u8981\u79F0\u8BE5\u4FE1\u4EF0\u4EE5\u8840\u732E\u796D\u3002"],["Any temple, its form and rites.","\u662F\u5426\u6709\u795E\u6BBF\uFF0C\u5176\u5F62\u5236\u4E0E\u4EEA\u5F0F\u3002"],["A simple hall with two horn-like spires; invented.","\u4E00\u5EA7\u5E26\u4E24\u6839\u89D2\u72B6\u5C16\u9876\u7684\u7B80\u6734\u6BBF\u5802\uFF1B\u7CFB\u81EA\u62DF\u3002"])}};export{d as default};
